{
  "model": "keep-me",
  "plugins": {
    "dirs": [
      "<ROOT>/home/plugins/inline-one"
    ],
    "enabledPlugins": {
      "mk@market": true
    }
  },
  "mcp": {
    "servers": {
      "fs": {
        "command": "npx",
        "args": [
          "-y",
          "@modelcontextprotocol/server-filesystem",
          "/x"
        ],
        "enabled": false
      },
      "legacy": {
        "command": "legacy",
        "enabled": false
      },
      "newsrv": {
        "type": "http",
        "url": "http://127.0.0.1:9/mcp"
      },
      "imported": {
        "command": "npx",
        "args": [
          "@modelcontextprotocol/server-filesystem",
          "<ROOT>/home/docs"
        ]
      }
    }
  },
  "hooks": {
    "events": {
      "UserPromptSubmit": [
        {
          "hooks": [
            {
              "type": "command",
              "command": "echo user",
              "enabled": true
            }
          ]
        }
      ]
    }
  },
  "skills": {
    "<ROOT>/home/.agents/skills/delta/SKILL.md": {
      "enable": false
    }
  },
  "command": {
    "<ROOT>/home/.zcode/commands/deploy2.md": {
      "enable": false
    }
  }
}
